// The Vertex sensor games (puttr-app components/play/sensorGames.js). Their games rows stay published = 0 with gameCat
// SENSOR on purpose, so the API never lists them: the app is their catalogue. The ids match those rows (saves go there).
// testerOnly entries (Waltz) show only for testers, as in the app. Their rules are SensorRuleGames.cs (RuleCatalog by
// gameType), their 3D worlds Scenes/<Name>Scene.cs, the stroke pairing SensorStroke.cs.
using System.Collections.Generic;

namespace PuttrApp
{
    public static class SensorGames
    {
        const string Json = "[{\"id\": 1601, \"gameType\": \"PENDULUM\", \"title\": \"Pendulum\", \"description\": \"The app sets the beat. Land your stroke tempo on it.\", \"rules\": \"Tempo is how quick your whole stroke is, in beats per minute (BPM): 60 divided by the seconds from takeaway to impact, so 72 BPM is a 0.83 second stroke and a higher number is a quicker stroke. Pick a target tempo and the metronome ticks at it: start back on one tick and strike the ball on the next. Every stroke's measured tempo swings the needle: land inside the pocket (within 3 bpm) and your streak multiplier climbs to x5, drift out and it resets. Points come from distance times tempo closeness times your multiplier, and a make adds 50%. 15 putts.\", \"difficulty\": 3, \"putts\": 15, \"distance\": 0, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}, {\"id\": 1489, \"gameType\": \"WALTZ\", \"title\": \"Waltz\", \"testerOnly\": true, \"description\": \"Three clicks: back, top, strike. Only your rhythm scores.\", \"rules\": \"Rhythm is your backstroke time divided by your forward stroke time, so 2.0:1 means the backstroke took twice as long as the move from the top to the ball. Pick a target rhythm (2.0:1 by default) and the metronome clicks it out: start back on the first click, reach the top on the second, strike on the third. Every stroke's measured rhythm swings the needle: land within 0.2 of your target and you are in time, worth 100 points, fading to zero at 0.7 off. Three in time in a row is a Waltz and doubles the putt, and a make adds 25%. The clicks change speed every 3 putts but the ratio never does. 15 putts.\", \"difficulty\": 4, \"putts\": 15, \"distance\": 0, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}, {\"id\": 1602, \"gameType\": \"PURE\", \"title\": \"Pure\", \"description\": \"Points for the stroke. The hole is just a multiplier.\", \"rules\": \"Every putt earns its purity, the average of your three Vertex accuracy scores (face change, rhythm, lie angle). Purity is the score and a make merely doubles it, so a dead-square lip-out still pays while a jabby lucky make earns almost nothing. Hit all three metrics green for a Pure Strike. 15 putts.\", \"difficulty\": 3, \"putts\": 15, \"distance\": 0, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}, {\"id\": 1603, \"gameType\": \"CARBONCOPY\", \"title\": \"Carbon Copy\", \"description\": \"Putt 1 records your signature stroke. Now clone it.\", \"rules\": \"Your first putt is free: its tempo, backstroke length, rhythm and face change become your signature. Every following putt is scored 0-100 on how closely it matches, and the tolerance tightens every 3 putts. A 90%+ match is a Carbon Copy and doubles. 1 signature + 14 copies, all from the tee and distance you pick.\", \"difficulty\": 5, \"putts\": 15, \"distance\": 6, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}, {\"id\": 1604, \"gameType\": \"SQUAREUP\", \"title\": \"Square Up\", \"description\": \"The face gate shrinks. Three balls. Stay square.\", \"rules\": \"Face change is your putter face angle at impact compared with address (plus is closed, minus is open). Every stroke's face change must stay inside the gate, which is centered on your own normal (found from 3 free putts) or on true zero, your choice. The gate starts at plus or minus 2 degrees and narrows every level (3 putts survived). Outside the gate costs a ball; lose all three and the run ends. Makes don't save you and misses don't kill you: only the face matters. Putt from the tee and distance you pick.\", \"difficulty\": 6, \"putts\": 0, \"distance\": 6, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}, {\"id\": 1605, \"gameType\": \"STRETCH\", \"title\": \"Stretch\", \"description\": \"Longer putt, longer stroke. The tempo never changes.\", \"rules\": \"Distances alternate short and long. Each distance shows a target backstroke length band in inches on a ruler: score for landing your stroke length in the band, keeping your tempo inside the band locked from your first 3 putts, and rolling out near the hole. All three at once is Elastic and doubles the putt. 12 putts.\", \"difficulty\": 5, \"putts\": 12, \"distance\": 0, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}, {\"id\": 1606, \"gameType\": \"LOCKDOWN\", \"title\": \"Lockdown\", \"description\": \"Six metrics, one ring. Keep every dial inside the band.\", \"rules\": \"Your first 3 putts draw your band, a hexagonal ring across six consistency metrics. Every stroke then plots its own hexagon: spokes inside the band score, a full hexagon is a Lockdown that tightens the band 5% and bumps your combo, and any break resets the combo and relaxes the band. Three straight putts with a break ends the run. Score is the tightest band reached. Putt from the tee and distance you pick, endless.\", \"difficulty\": 8, \"putts\": 0, \"distance\": 8, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}, {\"id\": 1607, \"gameType\": \"THEYIPS\", \"title\": \"The Yips\", \"description\": \"Smooth strokes hurt it. Handsy strokes feed it.\", \"rules\": \"The Yips monster has an HP bar and so do you. Damage comes from stroke quality times distance, with a made putt landing a critical x2. But when your face change twitches or your rhythm collapses, the monster strikes back and takes your HP. Three stages: the strike window tightens as it weakens, and stage 3 only respects smooth strokes. Kill it before it kills you.\", \"difficulty\": 6, \"putts\": 0, \"distance\": 0, \"multiPlayer\": 0, \"hasLeaderboard\": 0, \"isOnline\": 0, \"gameCat\": \"SENSOR\"}]";

        static List<object> _all;

        public static List<object> All
        {
            get
            {
                if (_all == null) _all = J.List(J.Parse(Json));
                bool tester = App.I != null && J.Flag(App.I.Profile, "isTester");
                return _all.FindAll(g => tester || !J.Flag(g, "testerOnly"));
            }
        }
    }
}
